class SheetOwnedCookTests(unittest.TestCase):
    def test_only_declared_product_edits(self):
        for f,(new,old) in FILES.items():
            self.assertEqual((ROOT/f).read_text(),new)
    def test_no_native_or_workflow_changes(self):
        for file,expected in PRESERVED.items():
            raw=(ROOT/file).read_bytes()
            if 'source:'+file in __import__('json').loads((ROOT/'scripts/tests/approved_merge_534_inverses.json').read_text())['contracts']:
                raw=normalize('source:'+file,raw)
            if file == 'AteUITests/CoverageUITests.swift':
                from settings_about_receipt_contract import original_coverage_bytes
                raw=original_coverage_bytes(raw)
            self.assertEqual(hashlib.sha256(raw).hexdigest(),expected,file)
    def test_cover_owned_by_origin_and_default_preserved(self):
        detail=(ROOT/'Ate/Views/RecipeDetailView.swift').read_text()
        sheet=(ROOT/'Ate/Views/ExpandableRecipeDetailSheet.swift').read_text()
        self.assertIn('else { store.cookTarget = CookTarget(id: recipeID) }',detail)
        self.assertIn('.fullScreenCover(item: $cookTarget',sheet)
        self.assertIn('store.cookJournalModalDismissing = true',sheet)
        self.assertIn('store.cookJournalModalDismissing = false',sheet)
        self.assertIn('JournalBoundCookMode(recipeID: target.id',sheet)

